#include <iostream>
class Base {
public:
  virtual void func() { std::cout << "Base::func()" << std::endl; }
  virtual ~Base() {} // Important for proper destruction in inheritance
};

class Derived : public Base {
public:
  void func() override { std::cout << "Derived::func()" << std::endl; }
};

int main() {
  Base* b = new Derived();
  b->func(); // Virtual function call
  delete b; //Crucial for proper cleanup in case of polymorphism
  return 0;
}
